#include "style/style_generator.h"

#include "common/cpp_string.h"

#include <QtCore/QDir>
#include <QtCore/QFile>
#include <QtCore/QFileInfo>

namespace codegen::style {
namespace {

const auto kHeader = QByteArray(
	"// WARNING! All changes made in this file will be lost!\n"
	"// Generated by codegen_style.\n");

[[nodiscard]] QByteArray StringLiteral(const QString &value) {
	return common::CppQString(value);
}

[[nodiscard]] QByteArray HexByte(quint32 value) {
	return "0x" + QByteArray::number(value & 0xFFU, 16).rightJustified(2, '0');
}

[[nodiscard]] QByteArray CppType(const Type &type) {
	switch (type.kind) {
	case TypeKind::Pixels:
	case TypeKind::Int:
	case TypeKind::Duration: return "int";
	case TypeKind::Double: return "double";
	case TypeKind::Bool: return "bool";
	case TypeKind::String: return "QString";
	case TypeKind::Color: return "style::color";
	case TypeKind::Font: return "style::font";
	case TypeKind::Margins: return "style::margins";
	case TypeKind::Size: return "style::size";
	case TypeKind::Point: return "style::point";
	case TypeKind::Icon: return "style::icon";
	case TypeKind::Align: return "style::align";
	case TypeKind::Struct: return "style::" + type.structName.toUtf8();
	case TypeKind::Invalid: break;
	}
	return "void";
}

[[nodiscard]] QByteArray FontFlags(int flags) {
	auto list = QList<QByteArray>();
	if (flags & FontBold) list.push_back("style::internal::FontBold");
	if (flags & FontSemibold) list.push_back("style::internal::FontSemibold");
	if (flags & FontMedium) list.push_back("style::internal::FontMedium");
	if (flags & FontItalic) list.push_back("style::internal::FontItalic");
	if (flags & FontUnderline) list.push_back("style::internal::FontUnderline");
	if (flags & FontStrikeOut) list.push_back("style::internal::FontStrikeOut");
	if (flags & FontMonospace) list.push_back("style::internal::FontMonospace");
	return list.isEmpty() ? QByteArray("0") : list.join(" | ");
}

[[nodiscard]] QByteArray ValueCode(const Value &value, int indent) {
	const auto number = [](int v) { return QByteArray::number(v); };
	switch (value.type.kind) {
	case TypeKind::Pixels:
	case TypeKind::Int:
	case TypeKind::Duration: return number(value.intValue);
	case TypeKind::Double: {
		auto result = QByteArray::number(value.doubleValue, 'g', 12);
		if (!result.contains('.') && !result.contains('e')) {
			result.append('.');
		}
		return result;
	}
	case TypeKind::Bool: return value.intValue ? "true" : "false";
	case TypeKind::String: return StringLiteral(value.stringValue);
	case TypeKind::Color:
		if (value.colorFromPalette) {
			return "st::" + value.colorName.toUtf8();
		}
		return "style::internal::LiteralColor("
			+ HexByte(value.colorRgba >> 24) + ", "
			+ HexByte(value.colorRgba >> 16) + ", "
			+ HexByte(value.colorRgba >> 8) + ", "
			+ HexByte(value.colorRgba) + ")";
	case TypeKind::Font:
		return "style::font("
			+ number(value.fontSize) + ", "
			+ FontFlags(value.fontFlags) + ", "
			+ (value.fontFamily.isEmpty()
				? QByteArray("QString()")
				: StringLiteral(value.fontFamily))
			+ ")";
	case TypeKind::Margins:
		return "style::margins("
			+ number(value.numbers[0]) + ", "
			+ number(value.numbers[1]) + ", "
			+ number(value.numbers[2]) + ", "
			+ number(value.numbers[3]) + ")";
	case TypeKind::Size:
		return "style::size("
			+ number(value.numbers[0]) + ", "
			+ number(value.numbers[1]) + ")";
	case TypeKind::Point:
		return "style::point("
			+ number(value.numbers[0]) + ", "
			+ number(value.numbers[1]) + ")";
	case TypeKind::Icon:
		return "style::icon("
			+ StringLiteral(value.stringValue) + ", "
			+ ValueCode(*value.iconColor, indent) + ", "
			+ number(value.iconSize) + ")";
	case TypeKind::Align: return "style::al_" + value.stringValue.toUtf8();
	case TypeKind::Struct: {
		const auto tabs = QByteArray(indent + 1, '\t');
		auto result = CppType(value.type) + "{\n";
		for (const auto &field : value.fields) {
			result += tabs + ValueCode(field, indent + 1) + ",\n";
		}
		result += QByteArray(indent, '\t') + "}";
		return result;
	}
	case TypeKind::Invalid: break;
	}
	return "{}";
}

[[nodiscard]] QByteArray RelativeTo(const QString &path) {
	return QFileInfo(path).fileName().toUtf8();
}

} // namespace

QList<GeneratedFile> GeneratePalette(const Palette &palette) {
	const auto count = QByteArray::number(palette.colors.size());

	auto header = kHeader;
	header += "// Source: " + RelativeTo(palette.path) + "\n";
	header += "#pragma once\n\n";
	header += "#include \"ui/style/style_core.h\"\n\n";
	header += "namespace style::internal {\n\n";
	header += "inline constexpr auto kPaletteColorsCount = " + count + ";\n\n";
	header += "} // namespace style::internal\n\n";
	header += "namespace st {\n\n";
	for (const auto &color : palette.colors) {
		header += "extern const style::color " + color.name.toUtf8() + ";\n";
	}
	header += "\n} // namespace st\n";

	const auto hex = [](quint32 value) {
		return "0x" + QByteArray::number(value, 16).rightJustified(8, '0').toUpper()
			+ "U";
	};
	auto source = kHeader;
	source += "#include \"styles/palette.h\"\n\n";
	source += "namespace style::internal {\nnamespace {\n\n";
	source += "ColorData Data[" + count + "];\n\n";
	source += "const PaletteRow Rows[" + count + "] = {\n";
	for (const auto &color : palette.colors) {
		source += "\t{ \"" + color.name.toUtf8() + "\", "
			+ hex(color.light) + ", " + hex(color.dark) + " },\n";
	}
	source += "};\n\n} // namespace\n\n";
	source += "PaletteDescriptor GeneratedPalette() {\n";
	source += "\treturn PaletteDescriptor{ Data, Rows, " + count + " };\n";
	source += "}\n\n} // namespace style::internal\n\n";
	source += "namespace st {\n\n";
	auto index = 0;
	for (const auto &color : palette.colors) {
		source += "const style::color " + color.name.toUtf8()
			+ "(&style::internal::Data[" + QByteArray::number(index++) + "]);\n";
	}
	source += "\n} // namespace st\n";

	return {
		GeneratedFile{ QStringLiteral("palette.h"), header },
		GeneratedFile{ QStringLiteral("palette.cpp"), source },
	};
}

QList<GeneratedFile> GenerateModule(const Module &module) {
	const auto name = module.name.toUtf8();

	auto header = kHeader;
	header += "// Source: " + RelativeTo(module.path) + "\n";
	header += "#pragma once\n\n";
	header += "#include \"ui/style/style_core.h\"\n";
	header += "#include \"styles/palette.h\"\n";
	for (const auto &included : module.includes) {
		header += "#include \"styles/style_" + included->name.toUtf8() + ".h\"\n";
	}
	header += "\n";
	if (!module.structs.isEmpty()) {
		header += "namespace style {\n\n";
		for (const auto &def : module.structs) {
			header += "struct " + def.name.toUtf8() + " {\n";
			for (const auto &field : def.fields) {
				header += "\t" + CppType(field.type) + " " + field.name.toUtf8();
				switch (field.type.kind) {
				case TypeKind::Pixels:
				case TypeKind::Int:
				case TypeKind::Duration: header += " = 0"; break;
				case TypeKind::Double: header += " = 0."; break;
				case TypeKind::Bool: header += " = false"; break;
				case TypeKind::Align: header += " = style::al_topleft"; break;
				default: break;
				}
				header += ";\n";
			}
			header += "};\n\n";
		}
		header += "} // namespace style\n\n";
	}
	header += "namespace style::internal {\n\n";
	header += "void init_style_" + name + "();\n\n";
	header += "} // namespace style::internal\n\n";
	header += "namespace st {\n\n";
	for (const auto &variable : module.variables) {
		header += "extern const " + CppType(variable.value.type) + " &"
			+ variable.name.toUtf8() + ";\n";
	}
	header += "\n} // namespace st\n";

	auto source = kHeader;
	source += "#include \"styles/style_" + name + ".h\"\n\n";
	source += "namespace {\n\n";
	source += "bool inited = false;\n\n";
	for (const auto &variable : module.variables) {
		source += CppType(variable.value.type) + " _" + variable.name.toUtf8()
			+ " = {};\n";
	}
	source += "\nconst style::internal::ModuleRegistrar registrar(\n"
		"\t&style::internal::init_style_" + name + ");\n";
	source += "\n} // namespace\n\n";
	source += "namespace st {\n\n";
	for (const auto &variable : module.variables) {
		source += "const " + CppType(variable.value.type) + " &"
			+ variable.name.toUtf8() + "(_" + variable.name.toUtf8() + ");\n";
	}
	source += "\n} // namespace st\n\n";
	source += "namespace style::internal {\n\n";
	source += "void init_style_" + name + "() {\n";
	source += "\tif (inited) {\n\t\treturn;\n\t}\n\tinited = true;\n\n";
	for (const auto &included : module.includes) {
		source += "\tinit_style_" + included->name.toUtf8() + "();\n";
	}
	if (!module.includes.isEmpty()) {
		source += "\n";
	}
	for (const auto &variable : module.variables) {
		source += "\t_" + variable.name.toUtf8() + " = "
			+ ValueCode(variable.value, 1) + ";\n";
	}
	source += "}\n\n} // namespace style::internal\n";

	return {
		GeneratedFile{ QStringLiteral("style_%1.h").arg(module.name), header },
		GeneratedFile{ QStringLiteral("style_%1.cpp").arg(module.name), source },
	};
}

bool WriteFiles(
		const QString &directory,
		const QList<GeneratedFile> &files,
		QString &error) {
	if (!QDir().mkpath(directory)) {
		error = QStringLiteral("could not create directory '%1'").arg(directory);
		return false;
	}
	for (const auto &generated : files) {
		const auto path = QDir(directory).filePath(generated.name);
		auto file = QFile(path);
		// Always rewrite: the build system tracks the outputs' timestamps.
		if (!file.open(QIODevice::WriteOnly | QIODevice::Truncate)
			|| file.write(generated.content) != generated.content.size()) {
			error = QStringLiteral("could not write '%1'").arg(path);
			return false;
		}
	}
	return true;
}

} // namespace codegen::style
